    # 4. empty input -> empty output
    assert _IgnoreUndefinedParameters.handle_from_dict(Sample, {}) == {}

    # 5. partial known parameters -> returned as-is, no error
    assert _IgnoreUndefinedParameters.handle_from_dict(
